 static void Png(string value){Check(value!=null&&value.Length<1500000,"texture bound");var b=Convert.FromBase64String(value);Check(b.Length>=33&&b[0]==137&&b[1]==80&&b[2]==78&&b[3]==71&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10&&b[12]==73&&b[13]==72&&b[14]==68&&b[15]==82&&b[16]==0&&b[17]==0&&b[18]==1&&b[19]==0&&b[20]==0&&b[21]==0&&b[22]==0&&b[23]==128,"bounded PNG header");var t=new Texture2D(2,2,TextureFormat.RGBA32,false,true);try{Check(ImageConversion.LoadImage(t,b)&&t.width==256&&t.height==128,"texture decode/dimensions");}finally{UnityEngine.Object.DestroyImmediate(t);}}
 public static Data Optional(Data d){if(d==null||(d.version==0&&d.assets==null))return null;try{Check(d.version==1&&d.units=="metres"&&d.axes=="Unity X/Y/Z","header");Check(d.assets!=null&&d.assets.Length<=1&&d.textures!=null&&d.textures.width==256&&d.textures.height==128,"bounded set");var found=new HashSet<string>();foreach(var a in d.assets){Check(a!=null&&ids.Contains(a.id)&&found.Add(a.id)&&a.assetKey=="tdj/"+a.id&&a.material=="mineLantern","identity");int n=a.positions?.Length/3??0;Check(n>0&&n<=12000&&a.positions.Length==n*3,"mesh bound");Floats(a.positions,n*3);Floats(a.normals,n*3);Floats(a.colors,n*3);Floats(a.uv,n*2);Floats(a.glow,n);Check(a.positions.All(x=>Mathf.Abs(x)<=4)&&a.normals.All(x=>Mathf.Abs(x)<=1.001f)&&a.colors.All(x=>x==1)&&a.glow.All(x=>x==0)&&a.uv.All(x=>x>=0&&x<=1),"mesh value");Check(a.triangles!=null&&a.triangles.Length>0&&a.triangles.Length<=12000&&a.triangles.Length%3==0&&a.triangles.All(x=>x>=0&&x<n),"indices");Check(Finite(a.radius)&&a.radius>=0&&a.radius<=4&&Finite(a.height)&&a.height>0&&a.height<=4&&Mathf.Abs(a.groundSink+1.65f)<1e-5,"catalog");if(!a.shape&&a.radius>0){Check(a.circleColliders!=null&&a.circleColliders.Length>0&&a.circleColliders.Length<=32,"circle proxies");foreach(var c in a.circleColliders){Floats(c.center,3);Check(c.center.All(x=>Mathf.Abs(x)<=4)&&Finite(c.radius)&&Mathf.Abs(c.radius-a.radius)<1e-6&&Finite(c.height)&&Mathf.Abs(c.height-a.height)<1e-6,"circle metadata");}}}

 Check(d.glass!=null&&d.light!=null,"glass/light");var g=d.glass;int gn=g.positions?.Length/3??0;Check(gn>0&&gn<1000,"glass bound");Floats(g.positions,gn*3);Floats(g.normals,gn*3);Floats(g.colors,gn*3);Floats(g.uv,gn*2);Floats(g.glow,gn);Check(g.positions.All(x=>Mathf.Abs(x)<2)&&g.normals.All(x=>Mathf.Abs(x)<=1.001f)&&g.colors.All(x=>x==1)&&g.glow.All(x=>x==0)&&g.uv.All(x=>x>=0&&x<=1)&&g.triangles!=null&&g.triangles.Length<3000&&g.triangles.Length%3==0&&g.triangles.All(x=>x>=0&&x<gn),"glass geometry");Floats(d.light.origin,3);Check(d.light.origin.All(x=>Mathf.Abs(x)<2)&&Finite(d.light.power)&&d.light.power>0&&d.light.power<=8&&Finite(d.light.range)&&d.light.range>0&&d.light.range<=8,"bounded light");
 Png(d.textures.colour);Png(d.textures.packed);Png(d.textures.normal);Png(d.textures.emission);return d;
 }catch(Exception e)when(e is InvalidDataException||e is FormatException||e is ArgumentException||e is NullReferenceException){Debug.LogWarning("Optional mine wall lantern ignored; existing assets retained: "+e.Message);return null;}}
 static Texture2D Normal(string png){var bytes=Convert.FromBase64String(png);var image=new Texture2D(2,2,TextureFormat.RGBA32,false,true);try{ImageConversion.LoadImage(image,bytes);var pixels=image.GetPixels32();for(int i=0;i<pixels.Length;i++)pixels[i].g=(byte)(255-pixels[i].g);image.SetPixels32(pixels);image.Apply();bytes=image.EncodeToPNG();}finally{UnityEngine.Object.DestroyImmediate(image);}string path=SharedImportCache.Root+"/mine-lantern-normal-"+SharedAssetFiles.Hash(bytes)+".png";var result=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(result)return result;Check(!File.Exists(path)&&!File.Exists(path+".meta"),"occupied texture path");File.WriteAllBytes(path,bytes);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.NormalMap;imp.sRGBTexture=false;imp.convertToNormalmap=false;imp.flipGreenChannel=false;imp.mipmapEnabled=true;imp.wrapMode=TextureWrapMode.Clamp;imp.filterMode=FilterMode.Trilinear;imp.anisoLevel=2;imp.maxTextureSize=512;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static float Number(string s){float n=float.Parse(s,CultureInfo.InvariantCulture);Check(Finite(n),"placement finite");return n;}
 public static int Build(string directory,string folder,Transform parent,Dictionary<string,GameObject> prefabs,SmallPropsV1.Data data){var d=data.mineLanternV1;if(d==null||d.assets.Length==0)return 0;var maps=d.textures;var colour=SharedImportCache.Image(Convert.FromBase64String(maps.colour),".png",true,true,TextureWrapMode.Clamp,FilterMode.Trilinear,2,512);var packed=SharedImportCache.Image(Convert.FromBase64String(maps.packed),".png",false,true,TextureWrapMode.Clamp,FilterMode.Trilinear,2,512);var normal=Normal(maps.normal);var shader=Shader.Find("Universal Render Pipeline/Lit");Check(shader&&shader.isSupported,"URP Lit");string matPath=folder+"/mine-lantern-shared.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(!material){Check(!File.Exists(matPath)&&!File.Exists(matPath+".meta"),"occupied material path");material=new Material(shader){name="Mine wall lantern",enableInstancing=true};AssetDatabase.CreateAsset(material,matPath);}material.shader=shader;material.SetColor("_BaseColor",Color.white);material.SetTexture("_BaseMap",colour);material.SetFloat("_Metallic",1);material.SetFloat("_Smoothness",1);material.SetFloat("_SmoothnessTextureChannel",0);material.SetTexture("_MetallicGlossMap",packed);material.EnableKeyword("_METALLICSPECGLOSSMAP");material.SetTexture("_BumpMap",normal);material.SetFloat("_BumpScale",.3f);material.SetTexture("_OcclusionMap",packed);material.SetFloat("_OcclusionStrength",.5f);material.EnableKeyword("_OCCLUSIONMAP");material.EnableKeyword("_NORMALMAP");material.SetTexture("_EmissionMap",SharedImportCache.Image(Convert.FromBase64String(maps.emission),".png",true,true,TextureWrapMode.Clamp,FilterMode.Trilinear,2,256));material.SetColor("_EmissionColor",Color.white*3f);material.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;material.EnableKeyword("_EMISSION");EditorUtility.SetDirty(material);
 string glassPath=folder+"/mine-lantern-glass.mat";var glassMat=AssetDatabase.LoadAssetAtPath<Material>(glassPath);if(!glassMat){Check(!File.Exists(glassPath)&&!File.Exists(glassPath+".meta"),"occupied glass material");glassMat=new Material(shader){name="Mine lamp thin clear glass",enableInstancing=true};AssetDatabase.CreateAsset(glassMat,glassPath);}glassMat.SetColor("_BaseColor",new Color(.776f,.835f,.812f,.16f));glassMat.SetFloat("_Metallic",.05f);glassMat.SetFloat("_Smoothness",.82f);glassMat.SetFloat("_Surface",1);glassMat.SetFloat("_Blend",0);glassMat.SetFloat("_SrcBlend",5);glassMat.SetFloat("_DstBlend",10);glassMat.SetFloat("_ZWrite",0);glassMat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glassMat.renderQueue=3000;glassMat.SetOverrideTag("RenderType","Transparent");EditorUtility.SetDirty(glassMat);
 var glassMesh=SmallPropsV1.MeshOf(d.glass.positions,d.glass.normals,d.glass.colors,d.glass.triangles,d.glass.glow);glassMesh=SharedImportCache.StoreMesh(glassMesh,"mine-lantern-glass/1\n"+JsonUtility.ToJson(d.glass));
 foreach(var a in d.assets){var mesh=SmallPropsV1.MeshOf(a.positions,a.normals,a.colors,a.triangles,a.glow);var uv=new Vector2[a.uv.Length/2];for(int i=0;i<uv.Length;i++)uv[i]=new Vector2(a.uv[2*i],1-a.uv[2*i+1]);mesh.uv=uv;mesh.RecalculateTangents();mesh=SharedImportCache.StoreMesh(mesh,"mine-lanterns/1\n"+JsonUtility.ToJson(a));var root=new GameObject(a.id);root.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=root.AddComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;renderer.shadowCastingMode=ShadowCastingMode.On;renderer.receiveShadows=true;
 var glass=new GameObject("Glass chimney");glass.transform.SetParent(root.transform,false);glass.AddComponent<MeshFilter>().sharedMesh=glassMesh;var gr=glass.AddComponent<MeshRenderer>();gr.sharedMaterial=glassMat;gr.shadowCastingMode=ShadowCastingMode.Off;gr.receiveShadows=false;root.AddComponent<RoomTorchInstance>().ConfigureLamp(new Vector3(d.light.origin[0],d.light.origin[1],d.light.origin[2]),d.light.power,d.light.range,a.id);
 if(a.radius>0){SmallPropsV1.Collider(root,a,mesh);}
 var prefab=PrefabUtility.SaveAsPrefabAsset(root,folder+"/small-"+a.id+".prefab");prefabs.Add(a.id,prefab);UnityEngine.Object.DestroyImmediate(root);}
 var fixtures=new List<RoomTorchInstance>();int placed=0;foreach(var line in File.ReadAllLines(Path.Combine(directory,"props.csv"))){var row=line.Split(',');if(row.Length!=11||!d.assets.Any(a=>a.id==row[1]&&a.assetKey==row[2]))continue;float sx=Number(row[7]),sy=Number(row[8]);Check(sx>0&&sy>0,"positive placement scale");var obj=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[row[1]],parent);obj.name=row[0];obj.transform.localPosition=new Vector3(Number(row[3]),Number(row[4]),Number(row[5]));obj.transform.localRotation=Quaternion.Euler(0,Number(row[6]),0);obj.transform.localScale=new Vector3(sx,sy,sx);var fixture=obj.GetComponent<RoomTorchInstance>();fixture.ConfigureLamp(new Vector3(d.light.origin[0],d.light.origin[1],d.light.origin[2]),d.light.power,d.light.range,row[0]);fixtures.Add(fixture);placed++;}if(fixtures.Count>0){var budget=parent.GetComponentInChildren<RoomTorchBudget>();if(!budget)budget=parent.gameObject.AddComponent<RoomTorchBudget>();budget.Configure(budget.Fixtures.Concat(fixtures).ToArray());}return placed;
 }
